private void checkMixedNinePatch(@NonNull ResourceContext context, @NonNull File folder) {
    File[] files = folder.listFiles();
    if (files == null) return;
    Map<String, File> map = new HashMap<>();
    for (File file : files) {
        String name = file.getName();
        if (name.endsWith(NINE_PATCH)) {
            map.put(name.substring(0, name.length() - NINE_PATCH.length()), file);
        }
    }
    for (File file : files) {
        String name = file.getName();
        if (name.endsWith(PNG) && !name.endsWith(NINE_PATCH)) {
            String base = name.substring(0, name.length() - PNG.length());
            File ninePatch = map.get(base);
            if (ninePatch != null) {
                String message = String.format(
                    "The resource `@drawable/%1$s` has both a PNG file (`%2$s`) and a 9-patch PNG file (`%3$s`), which both map to `@drawable/%1$s`. Rename one of them.",
                    base, name, ninePatch.getName());
                context.report(ISSUE_MIXED_NINE_PATCH, Location.create(file), message);
            }
        }
    }
}
